const mongoose = require('mongoose');
const { Schema } = mongoose;

// One SOX (Sarbanes-Oxley §404 / ICFR) control over the enterprise landscape —
// generated by scripts/seed_sox_controls.js from the real Application, API,
// Server, Software and Diagram (business flow) records, scoped the way an
// external auditor would scope a real-world ICFR audit: financially
// significant applications get IT General Controls (ITGCs), financially
// significant business flows get process-level controls on the tasks where a
// misstatement could enter the books, and cross-application APIs feeding
// those tasks get interface controls.
//
// controlId is the human-facing, unique identifier for the control:
//   SOX-ITGC-<domain><nn>-<APP_ID>   e.g. SOX-ITGC-AC02-LLM007   (app-level ITGC)
//   SOX-<cycle>-<nnn>                e.g. SOX-P2P-004            (business process control)
//   SOX-ITAC-IF-<API_ID>             e.g. SOX-ITAC-IF-API00012   (interface control)
//
// `anchors` holds the normalized keys the diagram canvas uses to place a
// control's icon (see GET /api/sox-controls/for-diagram/:id) — task names
// are the only reliable link back to a canvas element (Diagram.tasks[]._id
// has no relationship to the bpmn:task element id), same as the Jira-impact
// and Process Optimizer overlays.
const ScopeApplicationSchema = new Schema({
  name: String, // acronym, as stored on Diagram.tasks[].applications[].name
  appId: String,
  appName: String,
  businessCriticality: String,
  dataClassification: String,
}, { _id: false });

const ScopeFlowSchema = new Schema({
  diagramId: String,
  name: String,
  domain: String,
  subdomain: String,
}, { _id: false });

const ScopeTaskSchema = new Schema({
  diagramId: String,
  flowName: String,
  taskName: String,
  actor: String,
  applications: [String],
}, { _id: false });

const ScopeApiSchema = new Schema({
  apiId: String,
  name: String,
  endpoint: String,
  method: String,
  apiType: String,
  interactionScope: String,
}, { _id: false });

const ScopeServerSchema = new Schema({
  serverId: String,
  name: String,
  role: String,
  networkZone: String,
  patchingStatus: String,
  complianceStatus: String,
  backupStatus: String,
  encryptionStatus: String,
  criticalVulns: Number,
}, { _id: false });

const ScopeDatabaseSchema = new Schema({
  softwareId: String,
  name: String,
  version: String,
  serverId: String,
  function: String,
}, { _id: false });

const SoxControlSchema = new Schema({
  controlId: { type: String, required: true, unique: true, index: true },
  title: { type: String, required: true },
  description: { type: String, required: true }, // the control activity, as performed
  controlObjective: { type: String, default: '' },
  riskStatement: { type: String, default: '' }, // "what could go wrong"
  category: {
    type: String,
    required: true,
    enum: ['IT General Control', 'Business Process Control', 'IT Application Control', 'Interface Control'],
    index: true,
  },
  itgcDomain: { type: String, default: null }, // Access to Programs & Data / Program Change / Computer Operations / Program Development
  processCycle: { type: String, default: null, index: true }, // P2P, O2C, R2R, FIN, WAR, INV, H2R, INC, ITG
  processCycleName: { type: String, default: null },
  controlType: { type: String, enum: ['Preventive', 'Detective'], default: 'Preventive' },
  controlNature: { type: String, enum: ['Manual', 'Automated', 'IT-Dependent Manual'], default: 'Manual' },
  frequency: { type: String, default: 'Per transaction' },
  keyControl: { type: Boolean, default: true },
  assertions: { type: [String], default: [] },
  financialStatementAccounts: { type: [String], default: [] },
  controlOwner: { type: String, default: '' },
  performedBy: { type: String, default: '' },
  evidence: { type: String, default: '' },
  testingProcedure: { type: String, default: '' },
  sampleSize: { type: String, default: '' },
  auditRisk: { type: String, enum: ['High', 'Medium', 'Low'], default: 'Medium', index: true },
  auditRiskRationale: { type: String, default: '' },
  observations: { type: [String], default: [] }, // data-grounded facts an auditor would probe
  frameworkRefs: { type: [String], default: [] },
  // Controls this one depends on or is paired with — e.g. an automated
  // control's supporting ITGCs, a task control's interface controls, or the
  // flow-level review control's task controls.
  relatedControlIds: { type: [String], default: [] },
  // Deviations raised against this control (soxdeviations collection) —
  // written by scripts/seed_sox_deviations.js.
  deviationIds: { type: [String], default: undefined },
  openDeviationCount: { type: Number, default: undefined },
  status: { type: String, enum: ['Active', 'Draft', 'Retired'], default: 'Active' },
  scope: {
    level: { type: String, enum: ['application', 'businessFlow', 'task', 'api'], required: true },
    applications: { type: [ScopeApplicationSchema], default: [] },
    businessFlows: { type: [ScopeFlowSchema], default: [] },
    tasks: { type: [ScopeTaskSchema], default: [] },
    apis: { type: [ScopeApiSchema], default: [] },
    servers: { type: [ScopeServerSchema], default: [] },
    databases: { type: [ScopeDatabaseSchema], default: [] },
  },
  anchors: {
    diagramIds: { type: [String], default: [], index: true },
    taskKeys: { type: [String], default: [] }, // `${diagramId}|${normalized task name}`
    applicationKeys: { type: [String], default: [], index: true }, // normalized acronym
  },
  batchId: { type: String, index: true },
  generatedAt: { type: Date, default: Date.now },
}, { timestamps: true, collection: 'soxcontrols' });

module.exports = mongoose.models.SoxControl || mongoose.model('SoxControl', SoxControlSchema);
